"""Alembic environment: runs migrations against `Settings.database_url` (or `sqlalchemy.url`)."""

from __future__ import annotations

from alembic import context
from sqlalchemy import Connection

import app.db.models  # noqa: F401 - registers all tables on Base.metadata
from app.core.config import get_settings
from app.core.logging import configure_logging
from app.db.base import Base
from app.db.session import create_db_engine

config = context.config
target_metadata = Base.metadata

# Views are created by hand in migrations and mapped on ViewBase, never autogenerated.
VIEWS = frozenset({"ratings"})


def _include_object(
    obj: object, name: str | None, type_: str, reflected: bool, compare_to: object
) -> bool:
    return not (type_ == "table" and name in VIEWS)


def _database_url() -> str:
    return config.get_main_option("sqlalchemy.url") or get_settings().database_url


def _configure(**kwargs: object) -> None:
    context.configure(
        target_metadata=target_metadata,
        include_object=_include_object,
        render_as_batch=True,  # SQLite ALTER TABLE support
        compare_type=True,
        **kwargs,  # type: ignore[arg-type]
    )


def run_migrations_offline() -> None:
    _configure(url=_database_url(), literal_binds=True, dialect_opts={"paramstyle": "named"})
    with context.begin_transaction():
        context.run_migrations()


def _run_with_connection(connection: Connection) -> None:
    _configure(connection=connection)
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    connection = config.attributes.get("connection")
    if connection is not None:
        _run_with_connection(connection)
        return
    engine = create_db_engine(_database_url())
    try:
        with engine.connect() as conn:
            _run_with_connection(conn)
    finally:
        engine.dispose()


if not config.attributes.get("skip_logging_config"):
    configure_logging(get_settings().log_level)

if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
